18	#include <vulkan/vulkan.h>
19	#include <stdbool.h>
20	#include <stdio.h>
21	#include <stdlib.h>
22	#include <string.h>
23	
24	#define WIDTH   64u
25	#define HEIGHT  64u
26	#define FORMAT  VK_FORMAT_R8G8B8A8_UNORM
27	
28	#define CHECK(x) do {                                              \
29	   VkResult _r = (x);                                              \
30	   if (_r != VK_SUCCESS) {                                         \
31	      fprintf(stderr, "FAILED: %s -> VkResult %d\n", #x, (int)_r); \
32	      return 1;                                                    \
33	   }                                                               \
34	} while (0)
