38	{
39	   FILE *f = fopen(path, "rb");
40	   if (!f) { fprintf(stderr, "FAILED: cannot open %s\n", path); return NULL; }
41	   fseek(f, 0, SEEK_END);
42	   long sz = ftell(f);
43	   fseek(f, 0, SEEK_SET);
44	   uint32_t *buf = malloc((size_t)sz);
45	   if (buf && fread(buf, 1, (size_t)sz, f) != (size_t)sz) { free(buf); buf = NULL; }
46	   fclose(f);
47	   if (buf) *out_size = (size_t)sz;
48	   return buf;
49	}
