51	/* first memory type satisfying `want`; UINT32_MAX if none. */
52	static uint32_t
53	find_mem(const VkPhysicalDeviceMemoryProperties *mp, uint32_t bits,
54	         VkMemoryPropertyFlags want)
55	{
56	   for (uint32_t i = 0; i < mp->memoryTypeCount; i++)
57	      if ((bits & (1u << i)) &&
58	          (mp->memoryTypes[i].propertyFlags & want) == want)
59	         return i;
60	   return UINT32_MAX;
61	}
