63	static VkShaderModule
64	load_module(VkDevice dev, const char *path)
65	{
66	   size_t sz = 0;
67	   uint32_t *spv = read_spirv(path, &sz);
68	   if (!spv) return VK_NULL_HANDLE;
69	   VkShaderModuleCreateInfo smci = {
70	      .sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO,
71	      .codeSize = sz, .pCode = spv,
72	   };
73	   VkShaderModule sm = VK_NULL_HANDLE;
74	   if (vkCreateShaderModule(dev, &smci, NULL, &sm) != VK_SUCCESS)
75	      sm = VK_NULL_HANDLE;
76	   free(spv);
77	   return sm;
78	}
